const chatroom_name = msg.config.chatroom_name;
const safe_identifier = String(chatroom_name).replace(/[^\p{L}\p{N}_-]/gu, "_");
const sender_override = (msg.config.sender_name || "").trim() || null;

const wasos_config = {
    // Standard client contract fields                                                                                                                              
    client_system: "wasos",
    api_key: msg.payload.nonce,
    identifier: safe_identifier,
    name: sender_override || chatroom_name,
    timestamp: Date.now(),
    client_specific: {
        // Wasos-specific fields                                                                                                                                    
        username: msg.config.username,
        user_id: msg.payload.profileId || null,
        chatroom_name: chatroom_name,
        room_id: msg.room_id || null,
        group: msg.payload.groups || null,
        sender_override: sender_override,
        api: {
            key: msg.payload.nonce,
            expires: msg.payload.refresh_expires || null
        }
    }
};

msg.payload = wasos_config;
return msg;

if (
    msg.payload.wasos_username.length > 0 && 
    msg.payload.wasos_password.length > 0 &&
    msg.payload.wasos_chatroom_name.length > 0
    ) 
    {
        return msg;
    } else {
        node.error("missing wasos config in msg.payload: ", msg);
        return null
    }

const config = msg.payload;

msg.topic = config.client_system;

if (config.identifier && 
    config.client_specific.chatroom_name && 
    config.client_specific.api.key) {
    return msg;
} else {
    node.error("Wasos config not correctly configured", config);
    return null;
}

msg._login_response = msg.payload;

msg.url = global.get("parat_bridge").base_urls.wasos
    + "/api/chat/rooms/" + msg.config.chatroom_name;
msg.headers = {
    "x-api-key": msg.payload.nonce
};

return msg;

const room_id = msg.payload.id || null;

msg.payload = msg._login_response;
msg.room_id = room_id;
delete msg._login_response;

if (!room_id) {
    node.warn("Could not discover WaSOS room UUID");
    return null
}

return msg;
